"""Render paired-query evidence without showing query text or retrieved examples."""
import json

def render(root,page,tab,lang,labels):
 t=lambda z,e:e if lang else z;pre='../' if lang else ''
 a=json.loads((root/'data/matrix/qwen-bge-comparison.json').read_text('utf-8'))
 b='<section class="phase-hero"><p class="eyebrow">PAIRED COMPARISON / SAME RERANKER</p><h1>'+t('多用記憶體，Qwen 4B 換到哪些優勢？','What does the extra memory for Qwen 4B buy?')+'</h1><p class="lead">'+t('Qwen 4B 與 BGE-M3 都搭配 Qwen 0.6B 重排器，逐題比較同一批2,556題。結果支持英文檢索與候選召回的小幅優勢，沒有支持全面升級。','Qwen 4B and BGE-M3 use the same Qwen 0.6B reranker on 2,556 paired queries. The results show modest gains in English retrieval and candidate recall, not a universal case for upgrading.')+'</p></section>'
 b+='<section><h2>'+t('三位小數看得見差異，但差距仍小','Three decimals reveal a small difference')+'</h2><p>'+t('五分項平均nDCG為0.897334與0.895650，畫面顯示0.897與0.896；過去兩位小數都顯示0.90。平均Top-1反而是BGE組略高：81.82%對81.79%。不能把較高nDCG說成第一篇一定更準。','Five-task mean nDCG is 0.897334 versus 0.895650, displayed as 0.897 and 0.896; both previously rounded to 0.90. Mean Top-1 is slightly higher for BGE: 81.82% versus 81.79%. Higher nDCG does not guarantee a more accurate first result.')+'</p>'
 b+=tab([t('分項','Condition'),'Qwen nDCG','BGE nDCG','Qwen Top-1','BGE Top-1',t('Qwen多命中第一名（淨題數）','Net additional Qwen first-result hits')],[[labels[r['dataset']][lang],f'{r["ndcg10"]["qwen"]:.3f}',f'{r["ndcg10"]["bge"]:.3f}',f'{r["top1"]["qwen"]*100:.2f}%',f'{r["top1"]["bge"]*100:.2f}%',f'{r["top1"]["qwen_better_queries"]-r["top1"]["bge_better_queries"]:+d} / {r["queries"]}'] for r in a['conditions']])+'</section>'
 b+='<section><h2>'+t('較值得考慮的向度：英文，以及少漏掉候選文章','Where to consider it: English retrieval and fewer candidate misses')+'</h2><p>'+t('英文查英文的1,148題中，Qwen組第一名命中率89.81%，BGE組89.37%；Qwen獨有命中7題、BGE獨有命中2題，淨增加5題。英文nDCG也是五分項中增益最大的一項，差0.004410。中文查英文與中文查中文的nDCG稍高，但第一名分別少命中1題與2題。','Across 1,148 English-to-English queries, Qwen achieves 89.81% Top-1 versus BGE’s 89.37%: seven Qwen-only hits and two BGE-only hits, a net gain of five. English also has the largest task-level nDCG gain, 0.004410. Chinese-to-English and Chinese-to-Chinese nDCG are slightly higher, but first-result hits decrease by one and two queries, respectively.')+'</p><p>'+t('兩組使用同一重排器，主要差異入口是Embedder找到的候選清單。MLQA每題只有一筆標準相關文章：前50篇召回率等同是否把這篇找進來。Qwen在三方向分別多找回淨3、4、8題；英文方向有11題只有Qwen候選含正解、3題只有BGE含正解。這能給重排器更多補救機會，但不保證正解最後排第一。','With the same reranker, the main input difference is the embedder’s candidate list. Each MLQA query has one gold-relevant document, so Recall@50 also measures whether it enters the pool. Qwen retrieves a net three, four and eight additional gold documents in the three directions. In English, 11 are Qwen-only candidate hits and three are BGE-only. This gives reranking more opportunities, without guaranteeing first place.')+'</p>'
 b+=tab([t('MLQA方向','MLQA direction'),'Qwen Recall@50','BGE Recall@50',t('淨增加題數','Net additional queries')],[[labels[r['dataset']][lang],f'{r["recall50"]["qwen"]*100:.2f}%',f'{r["recall50"]["bge"]*100:.2f}%',str(r['recall50']['qwen_better_queries']-r['recall50']['bge_better_queries'])] for r in a['conditions'][:3]])+'</section>'
 b+='<section><h2>'+t('什麼情況值得多用容量？','When is the additional capacity worth considering?')+'</h2><p>'+t('兩組Q8_0權重合計為4.581與1.186 GiB，相差3.395 GiB，約3.86倍；這不是實測RAM用量，執行還需要向量索引與工作緩衝。若英文資料搜尋很重要、漏掉少數關鍵文件的代價高，而且你有餘裕，Qwen 4B可以列為升級候選，再用自己的題目驗證。若主要是中文第一名命中、記憶體有限，或資料相近於本次MIRACL子集，現有證據更支持先用BGE-M3＋Qwen 0.6B。','Combined Q8_0 weights are 4.581 versus 1.186 GiB: 3.395 GiB more, or about 3.86 times as much. These are not measured RAM requirements; indexes and buffers add overhead. Consider Qwen 4B if English retrieval matters, missing a few critical documents is costly, and capacity is available, then validate on your queries. For Chinese first-result hits, limited memory, or corpora resembling these MIRACL subsets, the evidence favors starting with BGE-M3 + Qwen 0.6B.')+'</p><p>'+t('MIRACL中文逐題nDCG全部相同，英文也只有1題不同；候選Recall@50兩組皆為100%，這個有限語料子集很難顯示更大Embedder的價值。ACORD重排修正尚未完成，因此不能拿舊法律分數替升級背書。此次也沒有按專業領域、問題長度或多跳推理進行有效分組，不能宣稱這些能力較強。','MIRACL Chinese per-query nDCG is identical, and English differs on only one query. Both achieve 100% candidate Recall@50; this bounded corpus cannot readily show the value of a larger embedder. Corrected ACORD reranking is pending, so old legal scores cannot justify upgrading. No validated breakdown by specialized domain, query length or multi-hop reasoning was performed, so no advantage on those dimensions is claimed.')+'</p><p>'+t('本機五項平均查詢時間為Qwen組1.116秒、BGE組1.166秒；模型分批測量、候選文章長度也可能不同，因此不把約50 ms差距解讀成大模型更快的普遍結論。','Local five-task mean query time is 1.116 s for Qwen and 1.166 s for BGE. Separate batches and potentially different candidate lengths prevent treating the roughly 50 ms gap as a general speed advantage for the larger model.')+'</p></section>'
 b+='<section><h2>'+t('逐題差異與不確定性','Per-query differences and uncertainty')+'</h2><p>'+t('2,556題中，nDCG有2,504題相同，Qwen較好27題、BGE較好25題。以下按同一題配對，以來源段落為群聚進行10,000次bootstrap，種子20261027。三個MLQA方向的nDCG差異95%區間均跨零；目前不足以宣稱穩定或顯著勝出。英文候選Recall@50的未校正區間高於零，但同時比較多項指標，仍應視為探索性結果。','Of 2,556 paired queries, 2,504 have equal nDCG; Qwen is better on 27 and BGE on 25. We use 10,000 paired source-passage-cluster bootstrap resamples, seed 20261027. All three MLQA nDCG difference intervals cross zero, so a reliable or significant win is not established. The unadjusted English candidate Recall@50 interval is above zero, but multiple metrics are compared; this remains exploratory.')+'</p>'
 b+=tab([t('分項','Condition'),t('Qwen較好／BGE較好／相同','Qwen better / BGE better / tied'),t('nDCG差異95%區間','95% interval for nDCG difference')],[[labels[r['dataset']][lang],f'{r["ndcg10"]["qwen_better_queries"]} / {r["ndcg10"]["bge_better_queries"]} / {r["ndcg10"]["ties"]}',f'[{r["ndcg10"]["paired_cluster_bootstrap_95"][0]:+.4f}, {r["ndcg10"]["paired_cluster_bootstrap_95"][1]:+.4f}]'] for r in a['conditions']])
 b+='<p class="small">'+t('區間未做多重比較校正；未估計跨語言相依的總平均區間。相同分數不代表檢索清單完全相同。逐題勝負不加權；首頁平均各分項等權，因此英文題較多不會占更高權重。','Intervals have no multiplicity correction; no overall interval models cross-language dependence. Equal scores do not imply identical ranked lists. Query win counts are unweighted; the homepage equally weights tasks, so more English queries do not give that task greater weight.')+'</p></section>'
 b+='<section><h2>'+t('完整配對資料與重算程式','Paired data and reproduction code')+'</h2><p><a href="'+pre+'data/matrix/qwen-bge-comparison.json">'+t('分項結果與區間JSON','Task results and intervals JSON')+'</a> · <a href="'+pre+'data/matrix/qwen-bge-paired-results.jsonl">'+t('2,556題配對分數','2,556 paired query scores')+'</a> · <a href="'+pre+'scripts/compare_qwen_bge.py">'+t('重算程式','Recomputation code')+'</a></p><p><code>python scripts/compare_qwen_bge.py</code> · Python / NumPy · '+t('無模型推論；原始B01/B05結果及授權見','No inference; original B01/B05 results and licenses:')+' <a href="latest-methods.html#downloads">'+t('方法與下載','Methods and downloads')+'</a></p></section>'
 return page('pair-comparison.html',t('Qwen 4B與BGE-M3：同一重排器的逐題比較','Qwen 4B vs BGE-M3: paired results with the same reranker'),b,lang)
